import tarfile
import contextlib
import six
from abc import ABCMeta, abstractmethod
from .exceptions import CorruptedArchive
try:
    from backports import lzma
except ImportError:
    import lzma


# TODO: find py2, py3 compatible method of inheriting docs
@six.add_metaclass(ABCMeta)
class ArchiveExtractor:
    @abstractmethod
    def extract(self, archive, destination):
        """
        Extract content of archive to destination directory.
            :archive: relative or absolute path (str)
            :destination: relative or absolute path (str), directory should
                          already exist
        """
        pass


# TODO: Change class names, it should rather be LZMAExtractor than
# AddonsExtractor (class name should not indicate what it is used for but what
# it does)
class AddonsExtractor(ArchiveExtractor):
    def extract(self, archive, destination):
        try:
            with contextlib.closing(lzma.LZMAFile(archive)) as xz:
                with tarfile.open(fileobj=xz) as f:
                    f.extractall(path=destination)
        except (lzma.LZMAError, EOFError):
            raise CorruptedArchive


class HeatTemplatesExtractor(ArchiveExtractor):
    def extract(self, archive, destination):
        try:
            with tarfile.open(archive, 'r:*') as t:
                t.extractall(path=destination)
        except tarfile.ReadError:
            raise CorruptedArchive
